    public static string GetIcon(string iconType)
    {
        return iconType.ToLower() switch
        {
            "settings" => SettingsIcon,
            "language" => LanguageIcon,
            "theme" => ThemeIcon,
            "tour" => TourIcon,
            "data" => DataIcon,
            "search" => SearchIcon,
            "list" => ListIcon,
            "paste" => PasteIcon,
            "clear" => ClearIcon,
            "number" => NumberIcon,
            "content" => ContentIcon,
            "file" => FileIcon,
            "folder" => FolderIcon,
            "export" => ExportIcon,
            "import" => ImportIcon,
            "save" => SaveIcon,
            "edit" => EditIcon,
            "delete" => DeleteIcon,
            _ => "M11,9H13V7H11M12,20C7.59,20 4,16.41 4,12C4,7.59 7.59,4 12,4C16.41,4 20,7.59 20,12C20,16.41 16.41,20 12,20M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2M11,17H13V11H11V17Z" // Help icon
